7	#include <tuple>
8	
9	// Return {kBlockM, kBlockN, MmaPV_is_RS, IntraWGOverlap}
10	constexpr std::tuple<int, int, bool, bool> tile_size_fwd_sm90(
11	        int headdim, int headdim_v, bool is_causal, bool is_local, int element_size=2,
12	        bool v_colmajor=false, bool paged_kv_non_TMA=false, bool softcap=false, bool use_one_mma_wg=false) {
13	    if (element_size == 2) {
14	        if (headdim <= 64) {
15	            // return {same_hdim ? 192 : 64, same_hdim ? 128 : 64, same_hdim, same_hdim};
16	            // With this workaround in Cutlass 3.8, tile size 192 x 128 got slower for non-causal, idk why
17	            // https://github.com/NVIDIA/cutlass/blob/833f6990e031b48b4cd2fcf55e0849c51ef6bac2/include/cute/container/tuple.hpp#L131
18	            if (headdim_v == 512) {
19	                return {64, 64, false, false};
20	            } else if (headdim_v == 256) {
21	                return {128, 96, true, false};
22	            } else {
23	                if (use_one_mma_wg) {
24	                    return {64, 192, true, true};
25	                } else {
26	                    // Switch to tile size 192 x 192 for now
27	                    // bool const use_blockN_128 = is_causal || is_local;
28	                    // return {192, use_blockN_128 ? 128 : 192, use_blockN_128, true}; // BASE
29	                    // Benefits SWA when window length <= 128
30	                    return {192, is_causal ? 128 : is_local || paged_kv_non_TMA ? 160 : 192, is_causal || is_local, !is_local};
31	                    // return {192, is_causal ? 128 : 160, true, !is_local};
32	                    // return {128, use_blockN_128 ? 160 : 192, use_blockN_128, !use_blockN_128};
33	                    // return {192, is_local ? 160 : 192, true, false};
34	                }
35	            }
36	            // Good for long seqlen (>= 4k) but suffers from tile quantization at short seqlen
37	            // return {192, is_causal || is_local ? 192 : 176, true, false};
38	        } else if (headdim <= 96) {
39	            return {192, is_local || paged_kv_non_TMA ? 128 : 144, false, true};
40	        } else if (headdim <= 128) {
41	            if (use_one_mma_wg) {
42	                return {64, is_causal || is_local || paged_kv_non_TMA ? 128 : 176, true, true};
43	            } else {
44	                return {128, is_causal || is_local || paged_kv_non_TMA ? 128 : 160, true, true};
45	            }
46	            // {128, 192, false, false} and {192, 128, false, true} are quite good too
47	            // 128 x 192 hits the limit of smem if MmaPV_is_RS, 128 x 144 hits the limit if !MmaPV_is_RS
48	        } else if (headdim <= 192) {
49	            return {128, paged_kv_non_TMA || is_local ? 96 : (headdim_v <= 128 ? 128 : 96), true, true};  // 128 x 112 hits the limit of smem
50	        } else {
51	            return {128, is_local ? 64 : 80, true, true};  // 128 x 80 hits the limit of smem
52	        }
53	    } else {
54	        // FP8 path
55	        if (use_one_mma_wg) {
56	            // Decode tiles — independent of two-level accumulation setting
57	            if (headdim <= 96) {
58	                return {64, 128, true, true};
59	            } else {
60	                return {64, 96, true, true};
61	            }
62	        } else {
63	            // Prefill tiles — two-level accumulation needs smaller tiles to reduce
64	            // register pressure from the separate fp32 accumulator (tOrO_accum).
65	            // Currently just optimized for causal case.
66	#ifndef FLASHATTENTION_DISABLE_FP8_TWO_LEVEL_ACCUMULATION
67	            if (headdim <= 64) {
68	                return {192, 128, true, true};
69	            } else if (headdim <= 96) {
70	                return {128, 128, true, true};
71	            } else if (headdim <= 128) {
72	                return {128, 192, true, true};
73	            } else if (headdim <= 192) {
74	                return {128, 96, true, true};
75	            } else {
76	                return {128, is_local ? 64 : 128, true, !paged_kv_non_TMA};  // TODO: FP8 prefill ~0.54x of BF16 with two-level accum at hd256
77	            }
78	#else
79	            if (headdim <= 64) {
80	                return {192, 160, true, true};
81	            } else if (headdim <= 96) {
82	                return {192, 128, true, true};
83	            } else if (headdim <= 128) {
84	                return {128, paged_kv_non_TMA ? 160 : (v_colmajor || (softcap && is_local) ? 192 : 224), true, true};
85	            } else if (headdim <= 192) {
86	                return {128, (paged_kv_non_TMA || softcap) && is_local ? 128 : 160, true, true};
87	            } else {
88	                return {128, is_local ? 64 : 128, true, !paged_kv_non_TMA};
89	            }
90	#endif
91	        }
92	    }
93	}
94	
95	// Return {kBlockM, kBlockN, kNWarps, kStages, Q_in_regs}
96	constexpr std::tuple<int, int, int, int, bool> tile_size_fwd_sm8x(
97	        bool sm86_or_89, int headdim, int headdim_v, bool is_causal, bool is_local, int element_size=2,
98	        bool paged_kv=false, bool varlen_and_split=false,
99	        bool softcap=false, bool append_kv=false) {
100	    if (element_size == 2) {
101	        if (headdim <= 64) {
102	            return {128, varlen_and_split ? 80 : (is_local ? 96 : 112), 4, 1, false};
103	        } else if (headdim <= 96) {
104	            return {128, varlen_and_split || is_local ? 48 : 64, 4, 1, false};
105	        } else if (headdim <= 128) {
106	            bool const use_8_warps = sm86_or_89 | varlen_and_split;
107	            return {128, use_8_warps ? (varlen_and_split ? (is_local ? 96 : 112) : (is_local ? 96 : 128)) : (is_local ? 48 : 64), use_8_warps ? 8 : 4, 1, use_8_warps};
108	        } else if (headdim <= 192) {
109	            bool const kBlockN_64 = append_kv || is_local || varlen_and_split || paged_kv;
110	            return {128, kBlockN_64 ? 64 : 96, 8, sm86_or_89 ? 1 : 2, !kBlockN_64};
111	        } else {
112	            return {128, sm86_or_89 ? (append_kv ? 32 : (varlen_and_split || is_local ? 48 : 64)) : (append_kv ? 48 : (varlen_and_split || is_local ? 64 : 96)), 8, 1, sm86_or_89 && !append_kv};
113	        }
114	    } else {
115	        // Placeholder for now
116	        return {128, 64, 8, 2, false};
117	    }
118	}
