434	inline bool get_pagedkv_tma(Flash_fwd_params const& params) {
435	    // disable for local since we move k_ptr to start of sliding window by m_block
436	    if (params.arch < 90 || !params.page_table || params.leftpad_k || params.knew_ptr || params.is_local) { return false; }
437	    // This needs to match the kernel configs
438	    auto kBlockMN_kernel_args_sm90 = tile_size_fwd_sm90(params.d_rounded, params.dv_rounded, params.is_causal, params.is_local, params.is_e4m3 ? 1 : 2 /*element_size*/, false /*v_colmajor*/, false /*paged_kv_non_TMA*/, params.softcap > 0.f, use_one_mma_wg(params));
439	    int const kBlockM = std::get<0>(kBlockMN_kernel_args_sm90);
440	    int const kBlockN = std::get<1>(kBlockMN_kernel_args_sm90);
441	    // Heuristic: when seqlen_q <= kBlockM, we're not compute bound, and somehow using TMA is slower,
442	    // at least for MLA.
443	    return params.page_size % kBlockN == 0 && params.seqlen_q * (params.h / params.h_k) > kBlockM;
444	}
