446	inline bool get_pack_gqa(Flash_fwd_params const& params) {
447	    // Always enable PackGQA for Sm8x or PagedKVNonTMA or Split to reduce compilation and binary size.
448	    // Has little effect on speed.
449	    if (params.arch < 90 || (params.page_table && !params.pagedkv_tma) || params.num_splits > 1) { return true; }
450	    #ifdef FLASHATTENTION_DISABLE_PACKGQA
451	    return false;
452	    #else
453	    // Always enable PackGQA for special case of hdim = 64, qheads/kvheads = 8, local attention
454	    // TODO: investigate more cases where PackGQA improves perf due to better tile quantization
455	    bool const packgqa_override = params.arch >= 90 && (params.h / params.h_k) == 8 && 
456	                                  params.is_local && 
457	                                  params.d == 64 && (params.dv == params.d);
458	    if (packgqa_override) { return true; }
459	    // params.page_table must already be set
460	    if (params.h == params.h_k) { return false; }
461	    // This needs to match the kernel configs
462	    auto kBlockMN_kernel_args_sm90 = tile_size_fwd_sm90(params.d_rounded, params.dv_rounded, params.is_causal, params.is_local, params.is_e4m3 ? 1 : 2 /*element_size*/, false /*v_colmajor*/, params.page_table && !params.pagedkv_tma, params.softcap > 0.f, use_one_mma_wg(params));
463	    int const kBlockM = std::get<0>(kBlockMN_kernel_args_sm90);
464	    return should_pack_gqa(params.cu_seqlens_q || params.seqused_q, params.seqlen_q, params.h / params.h_k, kBlockM);
465	    #endif
466	}
